SELECT 
FROM vso_purchase_agreement t
WHERE t.row_valid = 1

    AND t.sale_model_code = #{params.saleModelCode}


    AND t.agreement_code = #{params.agreementCode}


    AND t.agreement_status = #{params.agreementStatus}

ORDER BY t.sale_model_code ASC, t.agreement_code ASC, t.version_no DESC

SELECT FROM vso_purchase_agreement t WHERE t.row_valid = 1 AND t.agreement_status = 'active' AND t.agreement_code = #{agreementCode} AND (t.sale_model_code = #{saleModelCode} OR t.sale_model_code = 'GLOBAL')
AND t.version_no = #{versionNo}
AND (t.effective_from IS NULL OR t.effective_from <= #{now}) AND (t.effective_to IS NULL OR t.effective_to > #{now}) ORDER BY CASE WHEN t.sale_model_code = #{saleModelCode} THEN 0 ELSE 1 END ASC, t.version_no DESC
